/// <summary>
/// DebuC 22.09.23
/// </summary>
static void checkPartyId()
{
    NDXKumUmsCust          nDXKumUmsCust1, nDXKumUmsCust2;

    Query                   q1, q2;
    QueryRun                qr1, qr2;
    QueryBuildDataSource    qbds1, qbds2;
    ;

    q1 = new Query();
    qbds1 = q1.addDataSource(tablenum(NDXKumUmsCust));
    qbds1.orderMode(OrderMode::GroupBy);
    qbds1.addGroupByField(fieldnum(NDXKumUmsCust, CompanyId));
    qr1 = new QueryRun(q1);
    while (qr1.next())
    {
        nDXKumUmsCust1 = qr1.get(tablenum(NDXKumUmsCust));
        changecompany(nDXKumUmsCust1.CompanyId)
        {
            q2 = new Query();
            qbds2 = q2.addDataSource(tablenum(NDXKumUmsCust));
            qbds2.update(true);
            qbds2.addRange(fieldnum(NDXKumUmsCust, CompanyId)).value(nDXKumUmsCust1.CompanyId);
            qbds2.addRange(fieldnum(NDXKumUmsCust, Party)).value(SysQuery::valueEmptyString());
            qr2 = new QueryRun(q2);
            while (qr2.next())
            {
                ttsbegin;
                nDXKumUmsCust2 = qr2.get(tablenum(NDXKumUmsCust));
                nDXKumUmsCust2.Party = CustTable::find(nDXKumUmsCust2.CustAccount).Party;
                nDXKumUmsCust2.update();
                ttscommit;
            }
        }
    }
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "_FirmenNr">NDXCompanys</param>
/// <param name = "l_CustAccount">CustAccount</param>
/// <param name = "_Jahr">NDXYear</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXKumUmsCust</returns>
static NDXKumUmsCust find(NDXCompanys       _FirmenNr,
                       CustAccount     l_CustAccount,
                       NDXYear        _Jahr,
                       boolean _forUpdate = false)
{
    NDXKumUmsCust umsatz;
    ;
    umsatz.selectForUpdate(_forUpdate);

    if (_FirmenNr && l_CustAccount && _Jahr)
    {
        select umsatz
            //--> NDX/STABK/NDX_TASK1235003885/07.07.2015
            where   umsatz.Jahr         == _Jahr &&
                    umsatz.Companys        == _FirmenNr &&
                    umsatz.CustAccount  == l_CustAccount;
    }
    /*
        index hint KdNrIdx

        where   umsatz.Firma        == _FirmenNr    &&
                umsatz.CustAccount  == l_CustAccount        &&
                umsatz.Jahr         == _Jahr;
        */
    //<-- NDX/STABK/NDX_TASK1235003885/07.07.2015

    return umsatz;
}

