}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "_NDX_KumUmsCust">NDXKumUmsCust</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXKumUmsCust</returns>
client server static public NDXKumUmsCust findOrCreate(NDXKumUmsCust _NDX_KumUmsCust, boolean _forUpdate = false)
{
    NDXKumUmsCust      nDX_KumUmsCust;
    ;
    nDX_KumUmsCust = NDXKumUmsCust::findRecord(_NDX_KumUmsCust, _forUpdate);
    if (!nDX_KumUmsCust.RecId)
    {
        nDX_KumUmsCust = NDXKumUmsCust::create(_NDX_KumUmsCust);
    }

    return nDX_KumUmsCust;
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "_NDX_KumUmsCust">NDXKumUmsCust</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXKumUmsCust</returns>
client server static public NDXKumUmsCust findRecord(NDXKumUmsCust _NDX_KumUmsCust, boolean _forUpdate = false)
{
    NDXKumUmsCust   nDX_KumUmsCust;
    ;
    if (_forUpdate)
    {
        nDX_KumUmsCust.selectForUpdate(_forUpdate);
    }

    if (_NDX_KumUmsCust.CompanyId && _NDX_KumUmsCust.CustAccount && _NDX_KumUmsCust.Jahr)
    {
        select firstOnly    nDX_KumUmsCust
            where           nDX_KumUmsCust.CompanyId    == _NDX_KumUmsCust.CompanyId        &&
                            nDX_KumUmsCust.CustAccount  == _NDX_KumUmsCust.CustAccount      &&
                            nDX_KumUmsCust.Jahr         == _NDX_KumUmsCust.Jahr;
    }
    else if (_NDX_KumUmsCust.KdNr && _NDX_KumUmsCust.Companys && _NDX_KumUmsCust.Jahr)
    {
        select firstOnly    nDX_KumUmsCust
            where           nDX_KumUmsCust.KdNr         == _nDX_KumUmsCust.KdNr             &&
                            nDX_KumUmsCust.Companys      == _NDX_KumUmsCust.Companys           &&
                            nDX_KumUmsCust.Jahr         == _NDX_KumUmsCust.Jahr;
    }
    return nDX_KumUmsCust;
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "_NDX_KumUmsCust">NDXKumUmsCust</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXKumUmsCust</returns>
server static public NDXKumUmsCust create(NDXKumUmsCust _NDX_KumUmsCust, boolean _forUpdate = false)
{
    NDXKumUmsCust  nDX_KumUmsCust;
    ;
    try
    {
        ttsbegin;
        nDX_KumUmsCust.selectForUpdate(_forUpdate);
        nDX_KumUmsCust.CompanyId   = _nDX_KumUmsCust.CompanyId;
        nDX_KumUmsCust.CustAccount = _nDX_KumUmsCust.CustAccount;
        ndx_KumUmsCust.Party     = _nDX_KumUmsCust.Party;                   // NDX/PAFFH/NDX_TASK1235003633/20.02.2014
        nDX_KumUmsCust.KdNr        = _nDX_KumUmsCust.KdNr;
        nDX_KumUmsCust.Companys     = _nDX_KumUmsCust.Companys;
        nDX_KumUmsCust.Jahr        = _nDX_KumUmsCust.Jahr;
        nDX_KumUmsCust.insert();
        ttscommit;
    }
    catch
    {
        throw Error(strfmt("@NDX:NDXKumUmsCustNotCreated",  _nDX_KumUmsCust.KdNr));         // Datensatz in NDX_KumUmsCust [%1] kann nicht angelegt werden
    }

    return nDX_KumUmsCust;
}

/// <summary>
