void addUmsFromNDXUmsCust(NDXMonthBE monat, NDXUmsCust nDX_UmsCust)
{
    ;
    switch (monat)
    {
        case NDXMonthBE::January   :  
            this.Umsatz01 += ndx_umscust.SalesBalance; 
            this.CostAmount01 += nDX_UmsCust.costAmount() ;
            break;
